-- Database invariants complement Service validation; historical records remain protected by foreign keys.
CREATE TRIGGER "PurchaseOrder_insert_guard" BEFORE INSERT ON "PurchaseOrder" WHEN NOT (NEW.totalAmount >= 0 AND NEW.totalAmount <= 2000000000 AND NEW.status IN ('DRAFT','PENDING','APPROVED','PARTIAL','RECEIVED')) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "PurchaseOrder_update_guard" BEFORE UPDATE ON "PurchaseOrder" WHEN NOT (NEW.totalAmount >= 0 AND NEW.totalAmount <= 2000000000 AND NEW.status IN ('DRAFT','PENDING','APPROVED','PARTIAL','RECEIVED')) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "PurchaseOrderItem_insert_guard" BEFORE INSERT ON "PurchaseOrderItem" WHEN NOT (NEW.quantity > 0 AND NEW.quantity <= 1000000 AND NEW.receivedQuantity >= 0 AND NEW.receivedQuantity <= NEW.quantity AND NEW.unitPrice >= 0 AND NEW.unitPrice <= 1000000000 AND NEW.amount = NEW.quantity * NEW.unitPrice AND NEW.amount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "PurchaseOrderItem_update_guard" BEFORE UPDATE ON "PurchaseOrderItem" WHEN NOT (NEW.quantity > 0 AND NEW.quantity <= 1000000 AND NEW.receivedQuantity >= 0 AND NEW.receivedQuantity <= NEW.quantity AND NEW.unitPrice >= 0 AND NEW.unitPrice <= 1000000000 AND NEW.amount = NEW.quantity * NEW.unitPrice AND NEW.amount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "GoodsReceipt_insert_guard" BEFORE INSERT ON "GoodsReceipt" WHEN NOT (NEW.totalAmount >= 0 AND NEW.totalAmount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "GoodsReceipt_update_guard" BEFORE UPDATE ON "GoodsReceipt" WHEN NOT (NEW.totalAmount >= 0 AND NEW.totalAmount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "GoodsReceiptItem_insert_guard" BEFORE INSERT ON "GoodsReceiptItem" WHEN NOT (NEW.quantity > 0 AND NEW.amount = NEW.quantity * NEW.unitPrice AND NEW.amount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "GoodsReceiptItem_update_guard" BEFORE UPDATE ON "GoodsReceiptItem" WHEN NOT (NEW.quantity > 0 AND NEW.amount = NEW.quantity * NEW.unitPrice AND NEW.amount <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "StockBalance_insert_guard" BEFORE INSERT ON "StockBalance" WHEN NOT (NEW.quantity >= 0 AND NEW.quantity <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "StockBalance_update_guard" BEFORE UPDATE ON "StockBalance" WHEN NOT (NEW.quantity >= 0 AND NEW.quantity <= 2000000000) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "StockMovement_insert_guard" BEFORE INSERT ON "StockMovement" WHEN NOT (NEW.afterQuantity = NEW.beforeQuantity + NEW.quantity AND NEW.beforeQuantity >= 0 AND NEW.afterQuantity >= 0) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "StockMovement_update_guard" BEFORE UPDATE ON "StockMovement" WHEN NOT (NEW.afterQuantity = NEW.beforeQuantity + NEW.quantity AND NEW.beforeQuantity >= 0 AND NEW.afterQuantity >= 0) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "Payable_insert_guard" BEFORE INSERT ON "Payable" WHEN NOT (NEW.originalAmount >= 0 AND NEW.originalAmount <= 2000000000 AND NEW.paidAmount >= 0 AND NEW.paidAmount <= NEW.originalAmount AND NEW.status IN ('UNSETTLED','PARTIAL','SETTLED')) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
CREATE TRIGGER "Payable_update_guard" BEFORE UPDATE ON "Payable" WHEN NOT (NEW.originalAmount >= 0 AND NEW.originalAmount <= 2000000000 AND NEW.paidAmount >= 0 AND NEW.paidAmount <= NEW.originalAmount AND NEW.status IN ('UNSETTLED','PARTIAL','SETTLED')) BEGIN SELECT RAISE(ABORT, 'BUSINESS_CONSTRAINT'); END;
UPDATE "Role" SET permissions = json_insert(permissions, '$[#]', 'purchase:read') WHERE code = 'PURCHASE' AND json_valid(permissions) AND NOT EXISTS (SELECT 1 FROM json_each(permissions) WHERE value = 'purchase:read');
